"""Generate web/data.js from data/words.json (so index.html works from file://)."""
import json
from pathlib import Path

root = Path(__file__).resolve().parent.parent
data = json.loads((root / "data" / "words.json").read_text(encoding="utf-8"))
out = root / "web" / "data.js"
out.write_text(
    "// generated by tools/build_web_data.py - do not edit\n"
    "window.TH_DATA = " + json.dumps(data, ensure_ascii=False, indent=1) + ";\n",
    encoding="utf-8",
)
print("wrote", out)
